  ('9a5f58e6-c762-59c2-8d9c-cc96a6c71930'::uuid, 'taiju-yamashita-design-and-architecture', '山下泰树设计建筑事务所', 'Taiju Yamashita Design and Architecture', '山下泰樹建築デザイン事務所', 'https://tjda.com/en/', true);

