  ('d6f955db-b759-5a79-b866-d729ca96d29c'::uuid, '3a86512e-ffa7-59d8-942a-585622839947'::uuid, 'bonus-track-shimokitazawa', 'CASE-038', '/images/graduation/cases/case-038-bonus-track-shimokitazawa.jpg', 'morinakayasuaki / Figure 3 in Hiroki Nakajima, Sustainability 17(17), MDPI', 'MDPI', 'CC BY 4.0', 'https://www.mdpi.com/2071-1050/17/17/7583', 'exterior', true),
